<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne;
class MarketSnapshot extends Model { protected $fillable=['snapshot_time','market_score','risk_mode','market_trend','volatility','breadth_score','buy_signals','sell_signals','hold_signals','winning_sectors','losing_sectors','metadata']; protected $casts=['snapshot_time'=>'immutable_datetime','market_score'=>'float','volatility'=>'float','breadth_score'=>'float','winning_sectors'=>'array','losing_sectors'=>'array','metadata'=>'array']; public function assets():HasMany{return $this->hasMany(MarketAsset::class);} public function sectors():HasMany{return $this->hasMany(SectorSnapshot::class);} public function statistics():HasOne{return $this->hasOne(MarketStatistic::class);} }
